export const getGetWorkerSnapshotUrl = () => {
  return `/worker/snapshot`;
};

/**
 * @summary Read this account's execution inventory
 */
export const getWorkerSnapshot = async (options?: Parameters<typeof orvalFetch>[1]): Promise<RawSnapshot> => {
  return orvalFetch<RawSnapshot>(getGetWorkerSnapshotUrl(), {
    ...options,
    method: "GET",
  });
};

export const getCreateWorkerWorkspaceUrl = () => {
  return `/worker/workspaces`;
};

/**
 * @summary Create a worker workspace from controller context
 */
export const createWorkerWorkspace = async (
  workerCreateRequest: NonReadonly<WorkerCreateRequest>,
  options?: Parameters<typeof orvalFetch>[1],
): Promise<WorkspaceResponse> => {
  const getHeaders = (h?: NonNullable<RequestInit["headers"]>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
  return orvalFetch<WorkspaceResponse>(getCreateWorkerWorkspaceUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(workerCreateRequest),
  });
};

export const getRefreshWorkerContextUrl = ({ id }: RefreshWorkerContextPathParameters) => {
  return `/worker/workspaces/${encodeURIComponent(String(id))}/context`;
};

/**
 * @summary Refresh controller-supplied workspace context
 */
export const refreshWorkerContext = async (
  { id }: RefreshWorkerContextPathParameters,
  workspaceLaunchSpec: NonReadonly<WorkspaceLaunchSpec>,
  options?: Parameters<typeof orvalFetch>[1],
): Promise<void> => {
  const getHeaders = (h?: NonNullable<RequestInit["headers"]>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
  return orvalFetch<void>(getRefreshWorkerContextUrl({ id }), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(workspaceLaunchSpec),
  });
};
